BEGIN READ ONLY;
SET LOCAL statement_timeout = '5s';
SET LOCAL lock_timeout = '1s';
WITH expected(table_name,column_name) AS (VALUES ('components','id'),('components','sku'),('components','name'),('components','category'),('components','manufacturer'),('components','active'),('components','individually'),('components','in_kits'),('components','sale_price'),('components','kit_price'),('components','kit_price_quantity'),('components','updated_at'),('components','description'),('components','specs'),('inventory','component_id'),('inventory','quantity'),('inventory','stock_unit'),('admin_members','user_id')), evidence AS (SELECT e.table_name,e.column_name,c.data_type,c.udt_name,c.is_nullable,(c.column_name IS NOT NULL) AS present,CASE WHEN c.column_name IS NOT NULL THEN has_column_privilege('anon',format('%I.%I','public',e.table_name),e.column_name,'SELECT') ELSE false END AS anon_select,CASE WHEN c.column_name IS NOT NULL THEN has_column_privilege('authenticated',format('%I.%I','public',e.table_name),e.column_name,'SELECT') ELSE false END AS authenticated_select FROM expected e LEFT JOIN information_schema.columns c ON c.table_schema='public' AND c.table_name=e.table_name AND c.column_name=e.column_name ORDER BY e.table_name,e.column_name LIMIT 50), packed AS (SELECT count(*) AS row_count,coalesce(jsonb_agg(to_jsonb(evidence)),'[]'::jsonb) AS rows FROM evidence), result AS (SELECT row_count,jsonb_build_object('status','OK','rows',rows) AS report FROM packed) SELECT CASE WHEN row_count>=50 OR octet_length(report::text)>8192 THEN jsonb_build_object('status','HOLD_LIMIT') ELSE report END AS evidence FROM result;
ROLLBACK;
